head.b:skin:
/*
-----------------------------------------------
Win95 Blogger Theme
----------------------------------------------- */

:root {
  --desktop: #008080;
  --window: #c0c0c0;
  --shadow: #404040;
  --dark: #000;
  --light: #fff;
  --mid: #808080;
  --title-start: #000080;
  --title-end: #1084d0;
  --link: #0000ee;
  --asset-root: "https://cdn.jsdelivr.net/gh/JoeCat1207/win95.css-blogger-theme@master/assets";
}

* {
  box-sizing: border-box;
}

html {
  min-height: 100%;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 18px 18px 46px;
  background: var(--desktop);
  color: #111;
  font-family: "MS Sans Serif", Tahoma, Verdana, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.45;
}

a {
  color: var(--link);
}

img {
  max-width: 100%;
  height: auto;
}

button,
input,
textarea,
select {
  font: inherit;
}

.desktop {
  width: min(1180px, 100%);
  margin: 0 auto;
}

.desktop-icons {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  margin: 0 0 16px;
}

.desktop-icon {
  width: 76px;
  color: #fff;
  text-align: center;
  text-decoration: none;
  text-shadow: 1px 1px #000;
}

.desktop-icon img {
  display: block;
  width: 32px;
  height: 32px;
  margin: 0 auto 6px;
  image-rendering: pixelated;
}

.shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 18px;
  align-items: start;
}

.win-window,
.widget,
.post,
.comments,
.blog-pager,
.status-panel {
  background: var(--window);
  color: #111;
  border: 2px solid;
  border-top-color: var(--light);
  border-left-color: var(--light);
  border-right-color: var(--shadow);
  border-bottom-color: var(--shadow);
  box-shadow: 1px 1px 0 var(--dark);
}

.win-title,
.widget > h2,
.post-title,
.date-header,
.comments h4 {
  min-height: 24px;
  margin: 0;
  padding: 3px 8px 4px;
  background: linear-gradient(90deg, var(--title-start), var(--title-end));
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.win-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.window-controls {
  display: inline-flex;
  gap: 3px;
}

.window-controls span {
  display: grid;
  place-items: center;
  width: 16px;
  height: 14px;
  background: var(--window);
  color: #111;
  border: 2px solid;
  border-top-color: var(--light);
  border-left-color: var(--light);
  border-right-color: var(--shadow);
  border-bottom-color: var(--shadow);
  font-size: 10px;
  line-height: 1;
}

.win-body,
.widget-content,
.post-body,
.comments .comments-content,
.status-panel {
  padding: 12px;
}

.site-header .win-body {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
}

.site-header img {
  width: 48px;
  height: 48px;
  image-rendering: pixelated;
}

.site-title {
  margin: 0;
  font-size: clamp(24px, 4vw, 42px);
  line-height: 1.05;
}

.site-description {
  margin: 6px 0 0;
  color: #333;
}

.main-column,
.sidebar-column {
  display: grid;
  gap: 18px;
}

.main-section,
.sidebar-section {
  display: grid;
  gap: 18px;
}

.widget {
  overflow: hidden;
}

.widget ul,
.widget ol {
  margin: 0;
  padding-left: 20px;
}

.widget li + li {
  margin-top: 6px;
}

.post {
  overflow: hidden;
}

.post-title {
  font-size: 16px;
}

.post-title a {
  color: #fff;
  text-decoration: none;
}

.post-header,
.post-footer,
.byline,
.post-timestamp {
  color: #333;
  font-size: 12px;
}

.post-body {
  background: #fff;
  border: 2px inset #d0d0d0;
  margin: 12px;
}

.post-body blockquote {
  margin: 12px 0;
  padding: 10px 12px;
  background: #ffffe1;
  border: 1px solid var(--mid);
}

.post-body pre,
.post-body code {
  font-family: "Courier New", monospace;
}

.post-body pre {
  overflow: auto;
  padding: 10px;
  background: #000;
  color: #0f0;
}

.post-footer {
  padding: 0 12px 12px;
}

.blog-pager {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 10px;
}

.blog-pager a,
.button-95,
.Profile a.profile-link,
.post-footer a {
  display: inline-block;
  min-height: 24px;
  padding: 2px 10px 4px;
  background: var(--window);
  color: #111;
  text-decoration: none;
  border: 2px solid;
  border-top-color: var(--light);
  border-left-color: var(--light);
  border-right-color: var(--shadow);
  border-bottom-color: var(--shadow);
}

.blog-pager a:active,
.button-95:active,
.Profile a.profile-link:active,
.post-footer a:active {
  border-top-color: var(--shadow);
  border-left-color: var(--shadow);
  border-right-color: var(--light);
  border-bottom-color: var(--light);
}

.Label a {
  display: inline-block;
  margin: 0 4px 6px 0;
  padding: 1px 7px 3px;
  background: #fff;
  border: 1px solid var(--mid);
}

.status-panel {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  font-size: 13px;
}

.status-panel img {
  width: 16px;
  height: 16px;
  margin-top: 2px;
}

.comments {
  margin-top: 18px;
}

.comments .comments-content {
  background: #fff;
  margin: 12px;
  border: 2px inset #d0d0d0;
}

.taskbar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  height: 34px;
  padding: 3px 8px;
  background: var(--window);
  border-top: 2px solid var(--light);
  box-shadow: 0 -1px 0 var(--mid);
}

.start-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
  padding: 2px 10px 3px;
  background: var(--window);
  color: #111;
  border: 2px solid;
  border-top-color: var(--light);
  border-left-color: var(--light);
  border-right-color: var(--shadow);
  border-bottom-color: var(--shadow);
  font-weight: 700;
  text-decoration: none;
}

.start-button img,
.task-button img {
  width: 16px;
  height: 16px;
  image-rendering: pixelated;
}

.task-button {
  min-width: 0;
  padding: 3px 8px;
  border: 2px inset #d0d0d0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.clock {
  padding: 3px 8px;
  border: 2px inset #d0d0d0;
  white-space: nowrap;
}

::-webkit-scrollbar {
  width: 16px;
  height: 16px;
}

::-webkit-scrollbar-track {
  background: #c0c0c0;
}

::-webkit-scrollbar-thumb {
  background: #c0c0c0;
  border: 2px solid;
  border-top-color: var(--light);
  border-left-color: var(--light);
  border-right-color: var(--shadow);
  border-bottom-color: var(--shadow);
}

@media (max-width: 860px) {
  body {
    padding: 12px 12px 46px;
  }

  .shell {
    grid-template-columns: 1fr;
  }

  .desktop-icons {
    gap: 10px;
  }

  .desktop-icon {
    width: 68px;
    font-size: 12px;
  }

  .site-header .win-body {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .site-header img {
    width: 40px;
    height: 40px;
  }

  .taskbar {
    grid-template-columns: auto minmax(80px, 1fr) auto;
  }
}
